// Local orchestration with .NET Aspire: one `dotnet run` starts SQL Server and RabbitMQ containers,
// all four services, and the Aspire dashboard (logs, metrics, distributed traces).
// Credentials for the containers are generated by Aspire and kept in user-secrets, never in source.

var builder = DistributedApplication.CreateBuilder(args);

var sql = builder.AddSqlServer("sql");
var catalogDb = sql.AddDatabase("catalogdb");
var ordersDb = sql.AddDatabase("ordersdb");
var paymentsDb = sql.AddDatabase("paymentsdb");

var messaging = builder.AddRabbitMQ("messaging").WithManagementPlugin();

var catalog = builder.AddProject<Projects.OrderFlow_Catalog_Api>("catalog")
    .WithReference(catalogDb).WaitFor(catalogDb)
    .WithReference(messaging).WaitFor(messaging)
    .WithHttpHealthCheck("/health");

var orders = builder.AddProject<Projects.OrderFlow_Orders_Api>("orders")
    .WithReference(ordersDb).WaitFor(ordersDb)
    .WithReference(messaging).WaitFor(messaging)
    .WithReference(catalog).WaitFor(catalog)
    .WithHttpHealthCheck("/health");

builder.AddProject<Projects.OrderFlow_Payments_Worker>("payments")
    .WithReference(paymentsDb).WaitFor(paymentsDb)
    .WithReference(messaging).WaitFor(messaging);

builder.AddProject<Projects.OrderFlow_Gateway>("gateway")
    .WithReference(orders).WaitFor(orders)
    .WithReference(catalog).WaitFor(catalog)
    .WithExternalHttpEndpoints()
    .WithHttpHealthCheck("/health");

builder.Build().Run();
